package manifest

import (
	"errors"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"strings"

	"github.com/teandresmith/sqlgen/cmd/sqlgen/config"
)

// breadcrumbMarker is the leading HTML-comment provenance marker prepended to
// every sqlgen-authored breadcrumb file (PRD §30.3 *Breadcrumb ownership*).
// Its presence in a file's leading comment block is the single signal that
// sqlgen owns the file and may overwrite or stale-delete it; its absence (a
// hand-authored file, or one whose marker the user deleted to adopt it) makes
// the file off-limits. The marker deliberately avoids a "DO NOT EDIT" claim —
// ownership here is soft and adoptable.
const breadcrumbMarker = "<!-- Generated by sqlgen — manifest breadcrumb.\n" +
	"     sqlgen rewrites this file on each `sqlgen generate` and removes it when the manifest\n" +
	"     is disabled. To manage this file yourself, delete this comment; sqlgen will then never\n" +
	"     overwrite or remove it. -->"

// breadcrumbMarkerID is the literal the ownership check looks for in a file's
// leading comment block. It is a substring of breadcrumbMarker and is
// deliberately NOT part of the pasteable pointer block surfaced in the
// user-owned-file warning, so pasting that block into a hand-authored file does
// not hand the file to sqlgen.
const breadcrumbMarkerID = "Generated by sqlgen"

// BreadcrumbsInput carries everything EmitBreadcrumbs needs. The orchestrator
// populates it from the resolved config and the same in-memory Document that
// drove JSON / markdown emission.
//
// Signature note: like EmitJSON / EmitMarkdown, this takes a resolved-config
// view rather than loose scalars. Two further shape choices: (1) the "graph
// package also gets breadcrumbs" case is driven by GraphDir being non-empty
// rather than a separate bool; the orchestrator sets GraphDir to the resolved
// graph dir whenever GraphQL is enabled (nested under models or a top-level
// sibling — the breadcrumb pointer adapts via a relative path). (2) The
// user-owned-file warning is returned (not printed) so the caller decides how
// to surface it — gen.Generate has no warning channel today, and the CLI
// already owns the printWarnings path.
type BreadcrumbsInput struct {
	// Doc is the manifest document (read-only); breadcrumb pointers are derived
	// from Doc.Package, Doc.Dialect, and Doc.Entities.
	Doc *Document
	// Breadcrumbs is the resolved per-flag config. ClaudeMD / AgentsMD gate the
	// two breadcrumb files; PackageDoc (the models_gen.go doc-comment pointer) is
	// handled by the orchestrator, not here.
	Breadcrumbs config.BreadcrumbsConfig
	// OutputDir is the resolved <output.dir> where CLAUDE.md / AGENTS.md land.
	OutputDir string
	// MarkdownDir is the resolved markdown_dir (default "manifest"), relative to
	// OutputDir. Breadcrumb pointers into the manifest use it.
	MarkdownDir string
	// GraphDir, when non-empty, is the resolved graph package directory (nested
	// under models or a top-level sibling). Its presence causes graph/CLAUDE.md
	// and graph/AGENTS.md to be emitted there using the three-pointer graph
	// template, whose manifest back-pointer adapts to GraphDir's location via a
	// relative path (PRD §30.3 GraphQL breadcrumbs).
	GraphDir string
}

// EmitBreadcrumbs writes the agent-discoverable breadcrumb files that point at
// the manifest (PRD §30.3). CLAUDE.md and AGENTS.md are byte-identical (one
// rendered body, two paths); each is gated by its own sub-flag. When GraphDir is
// set (GraphQL enabled, graph package nested or a top-level sibling) the graph
// package additionally receives the three-pointer graph breadcrumbs.
//
// Every write honors the ownership rule: a target that is absent, or present
// with the provenance marker, is (over)written; a target present WITHOUT the
// marker (hand-authored, or user-adopted by deleting the marker) is left
// untouched and a warning describing it is returned. EmitBreadcrumbs never
// hard-fails on a user-owned file. The returned warnings are for the caller to
// surface (the CLI's printWarnings path).
func EmitBreadcrumbs(in BreadcrumbsInput) ([]string, error) {
	if in.Doc == nil {
		return nil, fmt.Errorf("emit manifest breadcrumbs: nil document")
	}
	mdDir := dirOrDefault(in.MarkdownDir, "manifest")

	var warnings []string

	modelsBody, err := renderMarkdown("breadcrumb.md.tmpl", modelsBreadcrumbData(in.Doc, mdDir))
	if err != nil {
		return nil, err
	}
	modelsIndex := "./" + path.Join(mdDir, "_index.md")
	ws, err := writeBreadcrumbPair(in.OutputDir, modelsBody, modelsIndex, in.Breadcrumbs)
	if err != nil {
		return nil, err
	}
	warnings = append(warnings, ws...)

	if in.GraphDir != "" {
		graphIndex := relIndexPath(in.GraphDir, in.OutputDir, mdDir)
		layeredBody, err := renderMarkdown("breadcrumb_layered.md.tmpl", layeredBreadcrumbData(in.Doc, graphIndex))
		if err != nil {
			return nil, err
		}
		ws, err := writeBreadcrumbPair(in.GraphDir, layeredBody, graphIndex, in.Breadcrumbs)
		if err != nil {
			return nil, err
		}
		warnings = append(warnings, ws...)
	}

	return warnings, nil
}

// writeBreadcrumbPair writes body to <dir>/CLAUDE.md and <dir>/AGENTS.md,
// each gated by its sub-flag and subject to the ownership rule. indexPath is the
// manifest _index.md pointer used in the user-owned-file warning. Returns any
// warnings from skipped user-owned targets.
func writeBreadcrumbPair(dir string, body []byte, indexPath string, cfg config.BreadcrumbsConfig) ([]string, error) {
	targets := []struct {
		enabled bool
		name    string
		flag    string
	}{
		{deref(cfg.ClaudeMD), "CLAUDE.md", "claude_md"},
		{deref(cfg.AgentsMD), "AGENTS.md", "agents_md"},
	}

	var warnings []string
	for _, t := range targets {
		if !t.enabled {
			continue
		}
		warn, err := writeBreadcrumb(filepath.Join(dir, t.name), body, indexPath, t.flag)
		if err != nil {
			return nil, err
		}
		if warn != "" {
			warnings = append(warnings, warn)
		}
	}
	return warnings, nil
}

// writeBreadcrumb applies the ownership rule (PRD §30.3) to a single target:
//   - absent            → write (with marker).
//   - present, marker   → overwrite (sqlgen-owned).
//   - present, no marker → skip; return a warning (user-owned).
func writeBreadcrumb(target string, body []byte, indexPath, flag string) (string, error) {
	existing, err := os.ReadFile(target) //nolint:gosec // target is a config-derived breadcrumb path
	switch {
	case errors.Is(err, os.ErrNotExist):
		// absent — fall through to write.
	case err != nil:
		return "", fmt.Errorf("emit manifest breadcrumb %s: %w", target, err)
	case hasSqlgenMarker(existing):
		// sqlgen-owned — fall through to overwrite.
	default:
		// user-owned — leave untouched, warn.
		return ownershipWarning(target, indexPath, flag), nil
	}

	if err := os.MkdirAll(filepath.Dir(target), 0o750); err != nil {
		return "", fmt.Errorf("emit manifest breadcrumb: %w", err)
	}
	if err := os.WriteFile(target, body, 0o600); err != nil {
		return "", fmt.Errorf("emit manifest breadcrumb: %w", err)
	}
	return "", nil
}

// BreadcrumbIsSqlgenOwned reports whether the file at path exists and carries the
// sqlgen provenance marker in its leading comment block. A missing file returns
// (false, nil) — absence is not ownership. This is the single source of truth for
// the marker check, shared by emission (this file) and the stale cleanup,
// which deletes a breadcrumb only when it is sqlgen-owned.
func BreadcrumbIsSqlgenOwned(path string) (bool, error) {
	content, err := os.ReadFile(path) //nolint:gosec // path is a config-derived breadcrumb path
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("checking breadcrumb ownership %s: %w", path, err)
	}
	return hasSqlgenMarker(content), nil
}

// hasSqlgenMarker reports whether content opens with an HTML comment block
// containing the sqlgen provenance marker. Only the leading comment block is
// consulted, so deleting the marker line (or the whole comment) from a prior
// sqlgen file disowns it on the next run.
func hasSqlgenMarker(content []byte) bool {
	s := strings.TrimLeft(string(content), " \t\r\n")
	if !strings.HasPrefix(s, "<!--") {
		return false
	}
	before, _, found := strings.Cut(s, "-->")
	if !found {
		return false
	}
	return strings.Contains(before, breadcrumbMarkerID)
}

// ownershipWarning renders the warning for a user-owned breadcrumb sqlgen left
// untouched (PRD §30.3 warning example): it names the file, offers the pasteable
// pointer block for agent auto-discovery, and cites the per-flag opt-out. The
// caller prefixes "Warning:" (the CLI's printWarnings path), so the message
// starts with the file path.
func ownershipWarning(target, indexPath, flag string) string {
	display := filepath.ToSlash(target)
	var b strings.Builder
	fmt.Fprintf(&b, "%s already exists and was not generated by sqlgen — leaving it untouched.\n", display)
	fmt.Fprintf(&b, "  For agent auto-discovery of the manifest, add this to %s:\n\n", display)
	for line := range strings.SplitSeq(pointerBlock(indexPath), "\n") {
		fmt.Fprintf(&b, "      %s\n", line)
	}
	fmt.Fprintf(&b, "\n  To silence this warning, set generation.manifest.breadcrumbs.%s: false", flag)
	return b.String()
}

// pointerBlock is the copy-pasteable manifest pointer offered in the
// user-owned-file warning. It deliberately does NOT carry the provenance marker,
// so pasting it into a hand-authored file does not make sqlgen adopt the file.
func pointerBlock(indexPath string) string {
	return "## Data-access surface (sqlgen)\n" +
		"See " + indexPath + " for the generated entities, methods, and conventions."
}

// breadcrumbEntity is one entity pointer rendered in the models breadcrumb.
type breadcrumbEntity struct {
	Name  string
	Table string
	Kind  string
	Path  string
}

// modelsBreadcrumb is the template data for breadcrumb.md.tmpl.
type modelsBreadcrumb struct {
	Package   string
	Dialect   string
	IndexPath string
	ConvPath  string
	Entities  []breadcrumbEntity
}

// layeredBreadcrumb is the template data for breadcrumb_layered.md.tmpl.
type layeredBreadcrumb struct {
	Package   string
	IndexPath string
}

// modelsBreadcrumbData projects the document onto the models breadcrumb data.
// Doc.Entities is already in the builder's stable order, so the pointer list is
// deterministic. Pointers are forward-slash, markdown-relative paths.
func modelsBreadcrumbData(doc *Document, mdDir string) modelsBreadcrumb {
	ents := make([]breadcrumbEntity, len(doc.Entities))
	for i := range doc.Entities {
		e := &doc.Entities[i]
		ents[i] = breadcrumbEntity{
			Name:  e.Name,
			Table: e.Table,
			Kind:  e.Kind,
			Path:  "./" + path.Join(mdDir, e.FilePrefix+".md"),
		}
	}
	return modelsBreadcrumb{
		Package:   doc.Package,
		Dialect:   doc.Dialect,
		IndexPath: "./" + path.Join(mdDir, "_index.md"),
		ConvPath:  "./" + path.Join(mdDir, "_conventions.md"),
		Entities:  ents,
	}
}

// layeredBreadcrumbData projects the document onto the layered breadcrumb data.
func layeredBreadcrumbData(doc *Document, indexPath string) layeredBreadcrumb {
	return layeredBreadcrumb{Package: doc.Package, IndexPath: indexPath}
}

// relIndexPath computes the manifest _index.md pointer from graphDir's
// perspective (PRD §30.3 GraphQL breadcrumbs — the pointer adapts whether graph
// is nested under output.dir or a top-level sibling). Output is forward-slash so
// the markdown stays portable across OSes. Falls back to the joined target if
// the two paths cannot be related (e.g. different Windows volumes).
func relIndexPath(graphDir, outputDir, mdDir string) string {
	target := filepath.Join(outputDir, mdDir, "_index.md")
	rel, err := filepath.Rel(graphDir, target)
	if err != nil {
		rel = target
	}
	return filepath.ToSlash(rel)
}

// deref reports the value of a nullable bool flag, treating a nil pointer as
// false. Resolved config fills these when the manifest is enabled; the nil-guard
// keeps the emitter safe against a partially-resolved config in tests.
func deref(p *bool) bool {
	return p != nil && *p
}
